arguments.content:
"""Run the repaired flush block under real torch.distributed collectives (gloo, 2 ranks).

The block is extracted from the repaired trainer source and executed by each rank with
the real accelerate `gather_object` and a real `accelerator.gather` (all_gather). Only
rank 0 logs `answer_parse_rate`, mirroring the staged reward function. A successful exit
means the collective sequences matched on both ranks and both recorded 0.75.
"""

import ast
import os
import textwrap

import torch
import torch.distributed as dist


def extract_flush_block(path):
    src = open(path).read()
    tree = ast.parse(src)
    for fn in ast.walk(tree):
        if isinstance(fn, ast.FunctionDef) and fn.name == "_generate_and_score_completions":
            for node in ast.walk(fn):
                if (
                    isinstance(node, ast.Assign)
                    and len(node.targets) == 1
                    and isinstance(node.targets[0], ast.Name)
                    and node.targets[0].id == "gathered_names"
                ):
                    lines = src.splitlines()
                    start = node.lineno - 1
                    end = next(j for j in range(start, start + 20) if "_pending_metrics.clear()" in lines[j]) + 1
                    return textwrap.dedent("\n".join(lines[start:end]))
    raise RuntimeError("repaired flush block not found")


class _Metrics(dict):
    def __missing__(self, key):
        self[key] = []
        return self[key]


class Accelerator:
    """Only the `gather` the block uses, backed by a real all_gather."""

    def __init__(self, rank, world):
        self.rank, self.world = rank, world

    def gather(self, tensor):
        out = [torch.empty_like(tensor) for _ in range(self.world)]
        dist.all_gather(out, tensor)
        return torch.stack(out)


def main():
    dist.init_process_group("gloo", init_method="env://")
    rank, world = dist.get_rank(), dist.get_world_size()
    from accelerate.utils import gather_object  # real implementation

    block = extract_flush_block("/workspace/src/trl/trainer/grpo_trainer.py")
    pending = {"answer_parse_rate": [0.75]} if rank == 0 else {}
    metrics = _Metrics()
    ns = {
        "gather_object": gather_object,
        "torch": torch,
        "mode": "train",
        "device": torch.device("cpu"),
        "self": Simple(pending, metrics, Accelerator(rank, world)),
    }
    exec(block, ns)

    got = metrics.get("answer_parse_rate")
    ok = got is not None and abs(got[0] - 0.75) < 1e-6
    print(f"rank {rank}: metrics={dict(metrics)} collectives completed -> {'OK' if ok else 'FAIL'}", flush=True)
    dist.barrier()
    dist.destroy_process_group()
    assert ok, f"rank {rank} recorded {got}"


class Simple:
    def __init__(self, pending, metrics, accelerator):
        self._pending_metrics = pending
        self._metrics = {"train": metrics, "eval": _Metrics()}
        self.accelerator = accelerator


if __name__ == "__main__":
    main()

